fn smallest_change(arr: Vec<i8>) -> usize {
    let n = arr.len();
    let mut diff_count = 0;

    // Only need to iterate over the first half of the array
    for i in 0..(n / 2) {
        if arr[i] != arr[n - 1 - i] {
            diff_count += 1;
        }
    }

    diff_count
}

